<include file="Public:header"/><link rel="stylesheet" href="{pigcms{$static_path}css/bootstrap.min.css"><link rel="stylesheet" href="{pigcms{$static_path}css/font-awesome.min.css?t=01"><link rel="stylesheet" href="{pigcms{$static_path}css/jquery-ui.css"><link rel="stylesheet" href="{pigcms{$static_path}css/jquery-ui.min.css"><link rel="stylesheet" href="{pigcms{$static_path}css/ace-fonts.css"><link rel="stylesheet" href="{pigcms{$static_path}css/ace.min.css" id="main-ace-style"><link rel="stylesheet" href="{pigcms{$static_path}css/ace-skins.min.css"><link rel="stylesheet" href="{pigcms{$static_path}css/ace-rtl.min.css"><link rel="stylesheet" href="{pigcms{$static_path}css/global.css"><link rel="stylesheet" href="{pigcms{$static_path}css/jquery-ui-timepicker-addon.css"><link rel="stylesheet" href="{pigcms{$static_public}layui/css/layui.css"  media="all"><style>    .table-list .summary {        margin: 10px 25px 5px 0 !important;        text-align: right !important;    }    .table-list .pager {        margin: 0 25px 5px 0 !important;        text-align: right !important;    }    .pager .next>a {        height: 30px;        line-height: 30px;    }    .pager .prev>a {        height: 30px;        line-height: 30px;    }   .input{ width: 300px;height: 30px;    line-height: 30px;}    .right_div{        display: inline-block;    margin-left: 50px;    }    .ant-btn {        line-height: 1.499;        position: relative;        display: inline-block;        font-weight: 400;        white-space: nowrap;        text-align: center;        background-image: none;        border: 1px solid transparent;        -webkit-box-shadow: 0 2px 0 rgb(0 0 0 / 2%);        box-shadow: 0 2px 0 rgb(0 0 0 / 2%);        cursor: pointer;        -webkit-transition: all 0.3s cubic-bezier(0.645, 0.045, 0.355, 1);        transition: all 0.3s cubic-bezier(0.645, 0.045, 0.355, 1);        -webkit-user-select: none;        -moz-user-select: none;        -ms-user-select: none;        user-select: none;        -ms-touch-action: manipulation;        touch-action: manipulation;        height: 32px;        padding: 0 15px;        font-size: 14px;        border-radius: 2px;        color: #fff;        background-color: #1890ff;        text-shadow: 0 -1px 0 rgb(0 0 0 / 12%);}</style>	<div class="mainbox">       <div class="tabbable" style="height: 60px;">        </div>      <div id="basicinfo_div" class="tab_div <if condition="$getparam['activetab'] eq 'datalist'">hide</if>" >        <input type="hidden" class="input set_input" name="block_type_id" value="{pigcms{$block_type_id}"/>        <input type="hidden" class="input set_input" name="village_id" value="{pigcms{$village_id}"/>        <div class="form-group">            <label class="col-sm-1" style="width: 15%;"><label>是否显示直播内容</label></label>            <div class="radio" style="padding-top: 5px;">                <label style="padding-left:0px;padding-right:20px;"><input name="is_show" value="1" type="radio" class="ace set_input"  <if condition="$nav_set AND $nav_set.is_show eq 1">checked</if> >&nbsp;<span class="lbl" style="z-index: 1">&nbsp;开启</span></label>                <label style="padding-left:0px;"><input name="is_show" value="0" type="radio" class="ace set_input" <if condition="empty($nav_set) OR ($nav_set AND $nav_set.is_show eq 0)">checked</if> >&nbsp;<span class="lbl" style="z-index: 1">&nbsp;关闭</span></label>            </div>        </div>        <div style="margin-left: 10px;color: #9a9999">            <span> 说明：</span>            <p>1、开关默认为关闭，开启时，小区首页会显示直播，点击直播可查看直播内容</p>            <p>2、如果是不显示状态下，小区首页不显示直播。</p>        </div>            <div style="text-align:center;margin-top: 50px;">               <button type="button" onclick="saveNavSetData()" class="ant-btn ant-btn-primary" >保存设置</button>           </div>        </div>	</div><script type="text/javascript" charset="utf-8">   function saveNavSetData(){       var inputArr=$('#basicinfo_div .set_input').serializeArray();       $.post("{pigcms{:U('save_village_nav_set')}",inputArr,function(result){            if(result.status != 1){                layer.alert('保存失败,请重试~ ');            }else{                layer.alert('保存成功！');            }        },'json');   }</script><include file="Public:footer"/>